+static bool isSharedConnection(const NetworkManager::Connection::Ptr &connection)
+{
+    if (!connection) {
+        return false;
+    }
+    const auto ipv4Setting = connection->settings()->setting(NetworkManager::Setting::Ipv4).dynamicCast<NetworkManager::Ipv4Setting>();
+    return ipv4Setting && ipv4Setting->method() == NetworkManager::Ipv4Setting::Shared;
+}
+
+void Handler::createUsbTethering()
+{
+    createUsbTetheringInternal();
+}
+
+QCoro::Task<> Handler::createUsbTetheringInternal()
+{
+    const NetworkManager::Device::Ptr device = usbGadgetDevice();
+
+    if (!device) {
+        qCWarning(PLASMA_NM_LIBS_LOG) << "Failed to enable USB tethering: missing USB gadget device";
+        co_return;
+    }
+
+    // Reuse a shared connection the user already made for this device
+    for (const NetworkManager::Connection::Ptr &connection : device->availableConnections()) {
+        if (isSharedConnection(connection)) {
+            activateConnection(connection->path(), device->uni(), QString());
+            co_return;
+        }
+    }
+
+    NetworkManager::ConnectionSettings::Ptr connectionSettings(new NetworkManager::ConnectionSettings(NetworkManager::ConnectionSettings::Wired));
+
+    NetworkManager::Ipv4Setting::Ptr ipv4Setting = connectionSettings->setting(NetworkManager::Setting::Ipv4).dynamicCast<NetworkManager::Ipv4Setting>();
+    ipv4Setting->setMethod(NetworkManager::Ipv4Setting::Shared);
+    ipv4Setting->setInitialized(true);
+
+    connectionSettings->setId(i18n("USB Tethering"));
+    connectionSettings->setAutoconnect(false);
+    connectionSettings->setUuid(NetworkManager::ConnectionSettings::createNewUuid());
+
+    const QVariantMap options = {{QLatin1String("persist"), QLatin1String("volatile")}};
+
+    QPointer<Handler> thisGuard(this);
+    QDBusPendingReply<QDBusObjectPath, QDBusObjectPath, QVariantMap> reply =
+        co_await NetworkManager::addAndActivateConnection2(connectionSettings->toMap(), device->uni(), QString(), options);
+    if (!thisGuard) {
+        co_return;
+    }
+
+    if (!reply.isValid()) {
+        KNotification *notification = new KNotification(QStringLiteral("FailedToActivateConnection"), KNotification::CloseOnTimeout, this);
+        notification->setTitle(i18n("Failed to enable USB tethering"));
+        notification->setComponentName(QStringLiteral("networkmanagement"));
+        notification->setText(reply.error().message());
+        notification->setIconName(QStringLiteral("dialog-warning"));
+        notification->sendEvent();
+    }
+}
+
+void Handler::stopUsbTethering()
+{
+    const NetworkManager::Device::Ptr device = usbGadgetDevice();
+    if (!device) {
+        return;
+    }
+
+    const NetworkManager::ActiveConnection::Ptr activeConnection = device->activeConnection();
+    if (activeConnection && isSharedConnection(activeConnection->connection())) {
+        NetworkManager::deactivateConnection(activeConnection->path());
+    }
+}
+
+NetworkManager::Device::Ptr Handler::usbGadgetDevice() const
+{
+    // All network functions of the Linux USB gadget stack report this driver, so this device is the USB peripheral, like a phone
+    for (const NetworkManager::Device::Ptr &device : NetworkManager::networkInterfaces()) {
+        if (device->type() == NetworkManager::Device::Ethernet && device->driver() == QLatin1String("g_ether")) {
+            return device;
+        }
+    }
+    return {};
+}
+
+void Handler::updateUsbTethering()
+{
+    const NetworkManager::Device::Ptr device = usbGadgetDevice();
+    const NetworkManager::ActiveConnection::Ptr activeConnection = device ? device->activeConnection() : nullptr;
+
+    const bool supported = !device.isNull();
+    const bool active = activeConnection && isSharedConnection(activeConnection->connection());
+
+    if (supported != m_usbTetheringSupported || active != m_usbTetheringActive) {
+        m_usbTetheringSupported = supported;
+        m_usbTetheringActive = active;
+        Q_EMIT usbTetheringChanged();
+    }
+}
